import React from "react";
import {
  FormItem,
  Input,
  Select,
  DatePicker,
  Editable,
  FormButtonGroup,
  Submit,
  Space,
  ArrayCards,
} from "@storage-fe/formily-arco";
import { createForm } from "@formily/core";
import { FormProvider, createSchemaField } from "@formily/react";

const SchemaField = createSchemaField({
  components: {
    FormItem,
    DatePicker,
    Editable,
    Space,
    Input,
    Select,
    ArrayCards,
  },
});
const form = createForm();

export default () => (
  <FormProvider form={form}>
    <SchemaField>
      <SchemaField.Array
        name="string_array"
        title="字符串数组"
        maxItems={3}
        x-decorator="FormItem"
        x-component="ArrayCards"
      >
        <SchemaField.Void>
          <SchemaField.Void x-component="ArrayCards.Index" />
          <SchemaField.String
            name="input"
            x-decorator="FormItem"
            title="Input"
            required
            x-component="Input"
          />
          <SchemaField.Void x-component="ArrayCards.Remove" />
          <SchemaField.Void x-component="ArrayCards.Copy" />
          <SchemaField.Void x-component="ArrayCards.MoveUp" />
          <SchemaField.Void x-component="ArrayCards.MoveDown" />
        </SchemaField.Void>
        <SchemaField.Void x-component="ArrayCards.Addition" title="Add entry" />
      </SchemaField.Array>
      <SchemaField.Array
        name="array"
        title="对象数组"
        maxItems={3}
        x-decorator="FormItem"
        x-component="ArrayCards"
      >
        <SchemaField.Object>
          <SchemaField.Void x-component="ArrayCards.Index" />
          <SchemaField.String
            name="input"
            x-decorator="FormItem"
            title="Input"
            required
            x-component="Input"
          />
          <SchemaField.Void x-component="ArrayCards.Remove" />
          <SchemaField.Void x-component="ArrayCards.MoveUp" />
          <SchemaField.Void x-component="ArrayCards.MoveDown" />
        </SchemaField.Object>
        <SchemaField.Void x-component="ArrayCards.Addition" title="Add entry" />
      </SchemaField.Array>
    </SchemaField>
    <FormButtonGroup>
      <Submit onSubmit={console.log}>Submit</Submit>
    </FormButtonGroup>
  </FormProvider>
);
